const OFFSET:u64=0xcbf29ce484222325;const PRIME:u64=0x100000001b3;
fn feed(h0:u64,v:i64)u64{var h=h0;var bits:u64=@bitCast(v);for(0..8)|_|{h=(h^(bits&255))*%PRIME;bits>>=8;}return h;}
export fn pareto_optimization(a:[*]const i64,len:usize)i64{if(len<2 or len>514)return -1;const r64=a[0];const c64=a[1];if(r64<1 or r64>64 or c64<1 or c64>8 or len!=2+@as(usize,@intCast(r64*c64)))return -1;const r:usize=@intCast(r64);const c:usize=@intCast(c64);for(0..r*c)|k|if(a[2+k]<-1000 or a[2+k]>1000)return -1;var keep:[64]bool=@splat(false);var kept:i64=0;for(0..r)|i|{keep[i]=true;for(0..r)|j|{if(i==j)continue;var ge=true;var gt=false;for(0..c)|x|{const l=a[2+j*c+x];const v=a[2+i*c+x];if(l<v)ge=false;if(l>v)gt=true;}if(ge and (gt or j<i)){keep[i]=false;break;}}if(keep[i])kept+=1;}var h=feed(OFFSET,kept);h=feed(h,c64);for(0..r)|i|{if(keep[i]){for(0..c)|x|h=feed(h,a[2+i*c+x]);}}return @intCast(h&0x7fffffffffffffff);}
